1	/**
2	 * @file host_pressure_monitor.cpp
3	 * @brief 采集端自身 CPU 压力监控器实现
4	 *
5	 * 数据路径：
6	 *   kmod/weaknet_cpu_stat.c（内核 hrtimer，4 ms）
7	 *     → /dev/weaknet_cpu_stat（只读 mmap，seqlock 保护）
8	 *     → HostCpuPressureSampler::sample()（区间差值 → 加权比率）
9	 *     → MetricsRegistry::publishScope(MetricScope::HOST, CPU_BUSY_RATIO)
10	 *     → quality 线程 / 诊断归因读取
11	 *
12	 * 为什么这里直接 include kmod/weaknet_kmod_abi.h：
13	 *   那个头文件的存在意义就是"内核模块与用户态共享同一份结构定义"
14	 *   （见其文件头声明）。如果在服务端另抄一份，一旦内核侧改动结构体，
15	 *   服务端会在毫无征兆的情况下读到错位数据——而这个驱动 30 分钟长稳测试
16	 *   专门验过 seqlock 不撕裂，恰恰说明"读到的是稳定但错误的字段"这种
17	 *   故障最难发现。共享定义让编译器直接报错。
18	 */
19	
20	#include "host_pressure_monitor.hpp"
21	
22	#include "server.hpp"
23	#include "logger.hpp"
24	#include "metrics/metrics_registry.hpp"
25	#include "metrics/metric_types.hpp"
26	#include "metrics/metric_sample.hpp"
27	
28	#include <cerrno>
29	#include <cstring>
30	#include <fcntl.h>
31	#include <sys/mman.h>
32	#include <sys/stat.h>
33	#include <unistd.h>
34	
35	// 内核与用户态共享的 ABI 定义（纯数据结构，不含内核专有头）
36	#include "../../kmod/weaknet_kmod_abi.h"
37	
38	namespace weaknet_dbus {
39	
40	namespace {
41	
42	/// seqlock 重试上限。正常写入窗口只覆盖一次 memcpy（8 核约 700 字节），
43	/// 用户态撞上奇数代次的概率极低；给足重试次数是为了在极端抢占下不误报失败。
44	constexpr int kMaxSeqRetry = 1000;
45	
46	/**
47	 * @brief 以 32 位 acquire 语义读 seq 的低半字。
48	 *
49	 * 为什么不直接读 64 位：内核写 seq 用的是 WRITE_ONCE（在 arm64 上 64 位
50	 * 写本身原子），但用户态通过 mmap 读到的是同一块普通内存页，理论上存在
51	 * 缓存别名。32 位访问在两条架构上都保证不撕裂，代价可以忽略。
52	 */
53	uint32_t loadSeq(const uint64_t* seq) {
54	    const volatile uint32_t* p = reinterpret_cast<const volatile uint32_t*>(seq);
55	    return __atomic_load_n(p, __ATOMIC_ACQUIRE);
56	}
57	
58	std::chrono::milliseconds readIntervalMs(const ServerContext* ctx) {
59	    const uint32_t ms = ctx->cfg.host_pressure.interval_ms.load();
60	    // 与配置层区间校验保持一致；越界值说明配置绕过了白名单，回落默认值而非崩溃
61	    if (ms < 1000 || ms > 600000) return std::chrono::milliseconds(15000);
62	    return std::chrono::milliseconds(ms);
63	}
64	
65	}  // namespace
66	
67	struct HostCpuPressureSampler::Impl {
68	    /// 单 CPU 的时间累计（纳秒），字段与 struct wn_cpu_stat 一一对应。
69	    struct CpuTimes {
70	        uint32_t cpu_id{0};
71	        bool online{false};
72	        bool valid{false};
73	        uint64_t busy{0};
74	        uint64_t total{0};
75	    };
76	
77	    std::vector<CpuTimes> prev;
78	    bool have_prev{false};
79	
80	    /// 映射在首次成功打开后保持，避免每轮 open/mmap 的开销
81	    int fd{-1};
82	    void* map{MAP_FAILED};
83	    size_t map_size{0};
84	};
85	
86	HostCpuPressureSampler::HostCpuPressureSampler(std::string dev_path)
87	    : dev_path_(std::move(dev_path)), impl_(std::make_unique<Impl>()) {}
88	
89	HostCpuPressureSampler::~HostCpuPressureSampler() {
90	    if (impl_ && impl_->map != MAP_FAILED) {
91	        munmap(impl_->map, impl_->map_size);
92	    }
93	    if (impl_ && impl_->fd >= 0) {
94	        close(impl_->fd);
95	    }
96	}
97	
98	HostCpuPressure HostCpuPressureSampler::sample() {
99	    HostCpuPressure out;
100	
101	    // ---- 1. 打开设备 + 映射（懒加载，失败后每轮重试，支持模块后插）----
102	    if (impl_->fd < 0) {
103	        impl_->fd = ::open(dev_path_.c_str(), O_RDONLY | O_CLOEXEC);
104	        if (impl_->fd < 0) {
105	            out.reason = "device_absent";
106	            return out;
107	        }
108	        impl_->map_size = sizeof(struct wn_cpu_snapshot);
109	        impl_->map = mmap(nullptr, impl_->map_size, PROT_READ, MAP_SHARED, impl_->fd, 0);
110	        if (impl_->map == MAP_FAILED) {
111	            out.reason = "mmap_failed";
112	            close(impl_->fd);
113	            impl_->fd = -1;
114	            return out;
115	        }
116	    }
117	
118	    // ---- 2. seqlock 读者：校验 → 拷贝 → 再校验 ----
119	    auto* snap = static_cast<struct wn_cpu_snapshot*>(impl_->map);
120	    struct wn_cpu_snapshot local;
121	
122	    uint32_t s0 = 0, s1 = 0;
123	    bool ok = false;
124	    for (int tries = 0; tries < kMaxSeqRetry; ++tries) {
125	        s0 = loadSeq(&snap->hdr.seq);
126	        if (s0 & 1u) continue;  // 内核正在写入
127	
128	        std::memcpy(&local, snap, sizeof(local));
129	
130	        // 拷贝完成后再校验一次：只在拷贝前校验会拿到半新半旧的数据
131	        __atomic_thread_fence(__ATOMIC_ACQUIRE);
132	        s1 = loadSeq(&snap->hdr.seq);
133	
134	        if (s0 == s1) {
135	            ok = true;
136	            break;
137	        }
138	    }
139	    if (!ok) {
140	        out.reason = "read_failed";
141	        return out;
142	    }
143	
144	    // ---- 3. ABI 版本校验：布局不符时宁可不可用，也不能拿错位数据当结论 ----
145	    if (local.hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
146	        out.reason = "abi_mismatch";
147	        return out;
148	    }
149	
150	    if (local.hdr.nr_cpus == 0) {
151	        out.reason = "no_delta_cpus";
152	        return out;
153	    }
154	
155	    // ---- 4. 转成差值友好的形态 ----
156	    std::vector<Impl::CpuTimes> cur;
157	    cur.reserve(local.hdr.nr_cpus);
158	    for (uint32_t i = 0; i < local.hdr.nr_cpus && i < WEAKNET_KMOD_MAX_CPUS; ++i) {
159	        const auto& c = local.cpu[i];
160	        Impl::CpuTimes t;
161	        t.cpu_id = c.cpu_id;
162	        t.online = (c.online != 0);
163	        t.valid = (c.valid != 0);
164	        // 与内核 ABI 头同口径：guest 已含在 user 内，不重复计入 busy
165	        t.busy = c.user + c.nice + c.system + c.irq + c.softirq + c.steal;
166	        t.total = t.busy + c.idle + c.iowait;
167	        cur.push_back(t);
168	    }
169	
170	    uint32_t online = 0;
171	    for (const auto& t : cur) {
172	        if (t.online) ++online;
173	    }
174	    out.online_cpus = online;
175	
176	    if (!impl_->have_prev) {
177	        impl_->prev = std::move(cur);
178	        impl_->have_prev = true;
179	        out.reason = "baseline_only";
180	        return out;
181	    }
182	
183	    // ---- 5. 区间差值 → 加权比率 ----
184	    //
185	    // 三个必须跳过的条件：
186	    //   a) 本轮离线
187	    //   b) 上一轮离线（离线期间累计冻结，上线后基准不对）
188	    //   c) valid=0（内核已判定这一对快照不可相减，如跨热插拔）
189	    //
190	    // 条件 c) 是内核侧显式给出的契约，不能自己用 "cur > prev" 之类的
191	    // 启发式去猜：一个恰好满足 cur > prev 的错误组合会算出荒唐值。
192	    uint64_t sum_busy = 0, sum_total = 0;
193	    uint32_t used = 0;
194	
195	    for (const auto& c : cur) {
196	        const Impl::CpuTimes* p = nullptr;
197	        for (const auto& pc : impl_->prev) {
198	            if (pc.cpu_id == c.cpu_id) {
199	                p = &pc;
200	                break;
201	            }
202	        }
203	        if (!p || !c.online || !p->online || !c.valid || !p->valid) continue;
204	        if (c.total < p->total || c.busy < p->busy) continue;  // 防御性：累计值不应倒退
205	
206	        sum_busy += (c.busy - p->busy);
207	        sum_total += (c.total - p->total);
208	        ++used;
209	    }
210	
211	    impl_->prev = std::move(cur);
212	
213	    if (used == 0 || sum_total == 0) {
214	        out.reason = "no_delta_cpus";
215	        return out;
216	    }
217	
218	    out.available = true;
219	    out.sampled_cpus = used;
220	    out.busy_ratio = static_cast<double>(sum_busy) / static_cast<double>(sum_total);
221	    // 数值防御：差值序列理论上不会越界，但除以极小 sum_total 时仍可能得到 >1
222	    if (out.busy_ratio > 1.0) out.busy_ratio = 1.0;
223	    if (out.busy_ratio < 0.0) out.busy_ratio = 0.0;
224	    return out;
225	}
226	
227	void start_host_pressure_monitor_thread(ServerContext* ctx, std::thread* worker) {
228	    // 可 join 句柄，由 MonitorManager 在停止时 join，避免 detached 线程在
229	    // ctx 析构后野访问（与 rtt_monitor 等既有监控器同一纪律）。
230	    *worker = std::thread([ctx] {
231	        LOG_INFO(LogModule::HOST_PRESSURE, "CPU pressure monitor thread started");
232	
233	        HostCpuPressureSampler sampler;
234	
235	        while (ctx->running.load() && !ctx->host_pressure_stop.load()) {
236	            try {
237	                const auto interval = readIntervalMs(ctx);
238	
239	                const HostCpuPressure p = sampler.sample();
240	
241	                if (ctx->metrics_registry) {
242	                    const auto sample = p.available
243	                        ? weaknet::MetricSample::valid(p.busy_ratio)
244	                        : weaknet::MetricSample::unavailable();
245	                    // 双发：与 server.cpp 的 TCP 重传/连接指标同一纪律。
246	                    // ctx->metrics_registry 服务评估侧读取（quality 线程归因），
247	                    // MetricsRegistry::global() 服务持久化侧读取
248	                    // （database_manager.cpp 的 insertSnapshot 只查 global）。
249	                    // 只发前者会让 CPU 压力永远进不了 SQLite——"看起来接好了、
250	                    // 实际永远 NULL"的典型陷阱。
251	                    ctx->metrics_registry->publishScope(
252	                        weaknet::MetricScope::HOST,
253	                        weaknet::MetricId::CPU_BUSY_RATIO,
254	                        sample);
255	                    weaknet::MetricsRegistry::global().publishScope(
256	                        weaknet::MetricScope::HOST,
257	                        weaknet::MetricId::CPU_BUSY_RATIO,
258	                        sample);
259	
260	                    if (p.available) {
261	                        LOG_INFO(LogModule::HOST_PRESSURE,
262	                                 "cpu_busy_ratio=" << p.busy_ratio
263	                                 << " (" << p.sampled_cpus << "/" << p.online_cpus
264	                                 << " cpus sampled)");
265	                    } else if (p.reason != "baseline_only") {
266	                        // 不可用时发布 UNAVAILABLE，**不发布 0**：
267	                        // 0 会被下游解读成"CPU 很闲"，从而掩盖真实故障。
268	                        // baseline_only 是启动后的正常状态，不值得刷警告
269	                        LOG_WARNING(LogModule::HOST_PRESSURE,
270	                                    "cpu pressure unavailable: " << p.reason);
271	                    }
272	                }
273	
274	                // 100 ms 分片等待：整段睡眠会让停止请求最长等一个完整周期
275	                const int slices = static_cast<int>(interval.count() / 100);
276	                for (int i = 0; i < slices && ctx->running.load() &&
277	                                !ctx->host_pressure_stop.load();
278	                     ++i) {
279	                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
280	                }
281	            } catch (const std::exception& e) {
282	                LOG_ERROR(LogModule::HOST_PRESSURE,
283	                          "CPU pressure monitor exception: " << e.what());
284	            } catch (...) {
285	                LOG_ERROR(LogModule::HOST_PRESSURE,
286	                          "CPU pressure monitor unknown exception");
287	            }
288	        }
289	
290	        LOG_INFO(LogModule::HOST_PRESSURE, "CPU pressure monitor thread exiting");
291	    });
292	}
293	
294	}  // namespace weaknet_dbus
