29	/**
30	 * @brief 纯机器确定性诊断事实（DiagnosisFacts）
31	 * 严格无任何大模型依赖，百分之百确定可测。
32	 */
33	struct DiagnosisFacts {
34	    std::string fault_domain{"UNKNOWN"};
35	    std::string primary_issue{"no_issue_detected"};
36	    std::vector<std::string> secondary_issues;
37	    DiagnosisConfidence confidence{DiagnosisConfidence::LOW};
38	
39	    std::vector<std::string> evidence_refs;
40	    std::vector<ExcludedCauseFact> excluded_causes;
41	    std::vector<ActionRequest> actions;
42	    std::string default_summary_template;
43	
44	    std::string toJson() const {
45	        using weaknet_utils::escapeJsonString;
46	        std::ostringstream oss;
47	        oss << "{\"fault_domain\":\"" << escapeJsonString(fault_domain) << "\","
48	            << "\"primary_issue\":\"" << escapeJsonString(primary_issue) << "\","
49	            << "\"confidence\":\"" << (confidence == DiagnosisConfidence::HIGH ? "HIGH" : (confidence == DiagnosisConfidence::MEDIUM ? "MEDIUM" : "LOW")) << "\",";
50	
51	        oss << "\"secondary_issues\":[";
52	        for (size_t i = 0; i < secondary_issues.size(); ++i) {
53	            oss << "\"" << escapeJsonString(secondary_issues[i]) << "\"" << (i + 1 < secondary_issues.size() ? "," : "");
54	        }
55	        oss << "],";
56	
57	        oss << "\"evidence_refs\":[";
58	        for (size_t i = 0; i < evidence_refs.size(); ++i) {
59	            oss << "\"" << escapeJsonString(evidence_refs[i]) << "\"" << (i + 1 < evidence_refs.size() ? "," : "");
60	        }
61	        oss << "],";
62	
63	        oss << "\"excluded_causes\":[";
64	        for (size_t i = 0; i < excluded_causes.size(); ++i) {
65	            oss << "{\"cause\":\"" << escapeJsonString(excluded_causes[i].cause)
66	                << "\",\"reason\":\"" << escapeJsonString(excluded_causes[i].reason) << "\"}"
67	                << (i + 1 < excluded_causes.size() ? "," : "");
68	        }
69	        oss << "],";
70	
71	        oss << "\"actions\":[";
72	        for (size_t i = 0; i < actions.size(); ++i) {
73	            oss << "{\"priority\":" << actions[i].priority
74	                << ",\"action_id\":\"" << escapeJsonString(actions[i].action_id) << "\",\"params\":{";
75	            size_t p_idx = 0;
76	            for (const auto& [k, v] : actions[i].params) {
77	                oss << "\"" << escapeJsonString(k) << "\":\"" << escapeJsonString(v) << "\"" << (++p_idx < actions[i].params.size() ? "," : "");
78	            }
79	            oss << "}}" << (i + 1 < actions.size() ? "," : "");
80	        }
81	        oss << "],";
82	
83	        oss << "\"default_summary_template\":\"" << escapeJsonString(default_summary_template) << "\"}";
84	        return oss.str();
85	    }
86	};
87	
88	class DiagnosisEngine {
89	public:
90	    explicit DiagnosisEngine(std::vector<DiagnosisRule> rules = RuleLoader::loadDefaultRules(),
91	                             std::shared_ptr<ActionRegistry> action_registry = std::make_shared<ActionRegistry>())
92	        : rules_(std::move(rules)), action_registry_(std::move(action_registry)) {}
93	
94	    DiagnosisFacts diagnose(const AssessmentSnapshot& snapshot, const EvidenceIdGenerator& id_gen) const {
95	        DiagnosisFacts facts;
96	
97	        // 1. 构建 FieldResolver
98	        auto resolver = buildResolver(snapshot);
99	
100	        // 2. 匹配规则与收集证据引用
101	        std::vector<MatchedRule> matches;
102	        uint32_t evidence_counter = 0;
103	
104	        for (const auto& r : rules_) {
105	            // trigger 检查
106	            const SleResult* sle = getSleByDomain(snapshot.experience, r.trigger_sle);
107	            if (!sle) continue;
108	            if (sle->reason != r.trigger_reason) continue;
109	
110	            // preconditions 检查 (Missing != false 原则)
111	            if (PredicateEngine::evaluateGroup(r.preconditions, resolver) != EvalResult::True) {
112	                continue;
113	            }
114	
115	            MatchedRule mr;
116	            mr.rule = &r;
117	            mr.confidence = r.base_confidence;
118	
119	            // 置信度升级算法
120	            if (PredicateEngine::evaluateGroup(r.upgrade_to_high_if, resolver) == EvalResult::True) {
121	                mr.confidence = DiagnosisConfidence::HIGH;
122	            }
123	
124	            // 绑定真实 Evidence ID
125	            for (size_t i = 0; i < sle->evidence.size(); ++i) {
126	                mr.evidence_refs.push_back(id_gen.generate(r.trigger_sle, snapshot.sequence_id, ++evidence_counter));
127	            }
128	            matches.push_back(std::move(mr));
129	        }
130	
131	        if (matches.empty()) {
132	            // 无规则命中时的默认事实
133	            if (snapshot.experience.overall == HealthState::GOOD) {
134	                facts.fault_domain = "NONE";
135	                facts.primary_issue = "all_metrics_healthy";
136	                facts.confidence = DiagnosisConfidence::HIGH;
137	                facts.default_summary_template = "当前网络各项体验指标均在健康阈值内，无需排查。";
138	            } else {
139	                facts.fault_domain = "UNKNOWN";
140	                facts.primary_issue = snapshot.experience.primary_issue.value_or("unspecified_issue");
141	                facts.confidence = DiagnosisConfidence::LOW;
142	                facts.default_summary_template = "当前网络指标存在异常但缺乏明确的判定规则，建议人工关注。";
143	            }
144	            return facts;
145	        }
146	
147	        // 3. 因果剪枝与冲突解决
148	        ResolvedDiagnosis resolved = CausalResolver::resolve(matches);
149	        const auto* primary_match = resolved.primary;
150	
151	        facts.fault_domain = primary_match->rule->domain;
152	        facts.primary_issue = primary_match->rule->trigger_reason;
153	        facts.confidence = primary_match->confidence;
154	        facts.default_summary_template = primary_match->rule->default_summary_template;
155	
156	        // 汇总证据
157	        for (const auto& ref : primary_match->evidence_refs) {
158	            facts.evidence_refs.push_back(ref);
159	        }
160	
161	        // 机器判定排除项：严格只在 when 谓词真值成立时写入
162	        for (const auto& ec : primary_match->rule->excluded_candidates) {
163	            if (PredicateEngine::evaluateGroup(ec.when, resolver) == EvalResult::True) {
164	                facts.excluded_causes.push_back({ec.cause, ec.explanation});
165	            }
166	        }
167	
168	        // 次要问题汇总
169	        for (const auto* sec : resolved.secondary) {
170	            facts.secondary_issues.push_back(sec->rule->trigger_reason);
171	            for (const auto& ref : sec->evidence_refs) {
172	                facts.evidence_refs.push_back(ref);
173	            }
174	        }
175	
176	        // 动作生成与 ActionRegistry 验证
177	        for (const auto& act_ref : primary_match->rule->actions) {
178	            auto val_res = action_registry_->validate(act_ref.action_id, act_ref.params);
179	            if (val_res.ok) {
180	                facts.actions.push_back({act_ref.priority, act_ref.action_id, act_ref.params});
181	            }
182	        }
183	
184	        return facts;
185	    }
186	
187	private:
188	    static const SleResult* getSleByDomain(const NetworkExperience& exp, const std::string& sle_name) {
189	        if (sle_name == "ip_reachability") return &exp.ip_reachability;
190	        if (sle_name == "responsiveness") return &exp.responsiveness;
191	        if (sle_name == "reliability") return &exp.reliability;
192	        if (sle_name == "rf_health") return &exp.rf_health;
193	        if (sle_name == "dns_service") return &exp.dns_service;
194	        if (sle_name == "tcp_connect") return &exp.tcp_connect;
195	        if (sle_name == "tcp_rtt") return &exp.tcp_rtt;
196	        if (sle_name == "http_access") return &exp.http_access;
197	        if (sle_name == "captive_portal") return &exp.captive_portal;
198	        if (sle_name == "active_dns") return &exp.active_dns;
199	        if (sle_name == "active_tcp") return &exp.active_tcp;
200	        if (sle_name == "active_https") return &exp.active_https;
201	        if (sle_name == "active_portal") return &exp.active_portal;
202	        return nullptr;
203	    }
204	
205	    PredicateEngine::FieldResolver buildResolver(const AssessmentSnapshot& snapshot) const {
206	        return [&snapshot](const std::string& field) -> std::optional<PredicateValue> {
207	            const auto& exp = snapshot.experience;
208	
209	            if (field == "overall_state") return healthStateToString(exp.overall);
210	            if (field == "link_type") {
211	                return (exp.iface.rfind("wl", 0) == 0) ? std::string("WIFI") : std::string("ETHERNET");
212	            }
213	            if (field == "ip_reachability.state") return healthStateToString(exp.ip_reachability.state);
214	            if (field == "ip_reachability.reason") return exp.ip_reachability.reason;
215	            if (field == "dns_service.state") return healthStateToString(exp.dns_service.state);
216	            if (field == "dns_service.reason") return exp.dns_service.reason;
217	            if (field == "rf_health.state") return healthStateToString(exp.rf_health.state);
218	            if (field == "rf_health.reason") return exp.rf_health.reason;
219	
220	            // 提取具体 EvidenceItem metric
221	            for (const auto* sle : {&exp.ip_reachability, &exp.responsiveness, &exp.reliability,
222	                                    &exp.rf_health, &exp.dns_service, &exp.tcp_connect,
223	                                    &exp.tcp_rtt, &exp.http_access, &exp.captive_portal}) {
224	                for (const auto& item : sle->evidence) {
225	                    if (field == item.metric) {
